import fs from 'node:fs';
import os from 'node:os';
import { execFileSync } from 'node:child_process';
import { chromium } from '/Users/noir/code/splashery/node_modules/playwright-core/index.mjs';
import { TOYS, holdsStill } from '/Users/noir/code/splashery/src/toys.js';
import { createScene } from '/Users/noir/code/splashery/src/state.js';

const root = '/Users/noir/code/splashery';
const out = `${root}/docs/audits/perf-2026-10`;
const chrome = '/Applications/Google Chrome.app/Contents/MacOS/Google Chrome';
const base = 'http://127.0.0.1:4173';
const pilot = process.argv.includes('--pilot');
const only = process.argv.find(a => a.startsWith('--device='))?.split('=')[1];
const definitions = [
  { name: 'phone', viewport: { width: 390, height: 844 }, deviceScaleFactor: 3, isMobile: true, hasTouch: true, profile: 'weak' },
  { name: 'desktop', viewport: { width: 1440, height: 900 }, deviceScaleFactor: 1, isMobile: false, hasTouch: false, profile: 'high' },
];
const write = (name, data) => fs.writeFileSync(`${out}/${name}`, JSON.stringify(data, null, 2) + '\n');
const args = ['--use-angle=metal', '--enable-webgl', '--ignore-gpu-blocklist', '--disable-background-timer-throttling', '--disable-renderer-backgrounding', '--disable-backgrounding-occluded-windows', '--enable-precise-memory-info'];
const browser = await chromium.launch({ executablePath: chrome, headless: true, args });
const catalogue = TOYS.map(t => ({ ...t, labs: !!t.labs }));
if (!pilot) {
  write('catalogue.json', catalogue);
  write('methodology.json', {
    startedAt: new Date().toISOString(), baseline: execFileSync('git', ['rev-parse', 'HEAD'], { cwd: root, encoding: 'utf8' }).trim(),
    browser: await browser.version(), executable: chrome, args, headless: true,
    host: { platform: os.platform(), release: os.release(), cpus: os.cpus().map(c => c.model), totalMemory: os.totalmem() },
    definitions, renderer: 'webgl2', network: 'localhost, no throttling, new isolated context per toy, CDP cache disabled',
    sound: 'off (clean localStorage)', options: 'default look and options, fixed scene seed 424242',
    loadMetric: 'navigation start to first postrender after body[data-ready=true] for the requested toy; hook installed before toy loading',
    windowMs: 5000, settleAfterReadyMs: 1500,
    frameMetric: 'wall-clock intervals between PlayCanvas frameend events; includes update-only loops because rendering is on demand; separate rendered-frame counts and postrender times retained',
    percentile: 'nearest rank: sorted[ceil(p*n)-1], median uses p=.5',
    heapMetric: 'CDP Runtime.getHeapUsage.usedSize at first-ready frame, without forced GC; excludes workers, native/GPU memory and media buffers',
    transferMetric: 'sum of CDP Network.loadingFinished.encodedDataLength for HTTP(S) responses, including response headers; opening cutoff is first-ready rendered frame; separate full-window total and payload Content-Length retained',
    collectorSource: fs.readFileSync('/tmp/splashery-perf-audit.mjs', 'utf8'),
  });
}
let n = 0;
try {
  for (const def of definitions.filter(d => !only || d.name === only)) {
    const filename = `${pilot ? 'pilot-' : ''}${def.name}.json`;
    let rows = fs.existsSync(`${out}/${filename}`) ? JSON.parse(fs.readFileSync(`${out}/${filename}`, 'utf8')) : [];
    const selected = pilot ? TOYS.filter(t => ['cactus', 'heart', 'your-book'].includes(t.id)) : TOYS;
    for (const toy of selected) {
      if (rows.some(r => r.id === toy.id && r.status === 'ok' && (r.collectorVersion >= 3 || (r.collectorVersion === 2 && !r.requests.some(q => q.type === 'Script' && q.status === undefined))))) continue;
      const context = await browser.newContext({ viewport: def.viewport, deviceScaleFactor: def.deviceScaleFactor, isMobile: def.isMobile, hasTouch: def.hasTouch, reducedMotion: 'no-preference', colorScheme: 'light', serviceWorkers: 'block' });
      const page = await context.newPage();
      const cdp = await context.newCDPSession(page);
      await cdp.send('Network.enable');
      await cdp.send('Network.setCacheDisabled', { cacheDisabled: true });
      await cdp.send('Performance.enable');
      const requests = new Map();
      const errors = [];
      const consoleErrors = [];
      let phase = 'opening';
      cdp.on('Network.requestWillBeSent', e => {
        if (/^https?:/.test(e.request.url)) requests.set(e.requestId, { url: e.request.url, type: e.type, phaseStarted: phase });
      });
      cdp.on('Network.responseReceived', e => {
        const r = requests.get(e.requestId);
        if (r) Object.assign(r, { status: e.response.status, mimeType: e.response.mimeType, responseHeaders: e.response.headers, fromDiskCache: e.response.fromDiskCache, fromServiceWorker: e.response.fromServiceWorker });
      });
      cdp.on('Network.loadingFinished', e => {
        const r = requests.get(e.requestId);
        if (r) Object.assign(r, { encodedBytes: e.encodedDataLength, finishTimestamp: e.timestamp, phaseFinished: phase });
      });
      cdp.on('Network.loadingFailed', e => {
        const r = requests.get(e.requestId);
        if (r) Object.assign(r, { error: e.errorText, canceled: e.canceled, phaseFinished: phase });
      });
      page.on('pageerror', e => errors.push(e.message));
      page.on('console', e => { if (e.type() === 'error') consoleErrors.push(e.text()); });
      await page.addInitScript(({ id }) => {
        performance.setResourceTimingBufferSize(2000);
        window.__perf = { id, firstReadyRenderMs: null, readyMs: null, frameends: [], renders: [], actions: [], windows: [] };
        const attach = () => {
          const p = window.__splashery?.player;
          if (!p?.stage) return requestAnimationFrame(attach);
          const a = window.__perf;
          p.stage.app.on('frameend', () => a.frameends.push(performance.now()));
          p.stage.app.on('postrender', () => {
            const now = performance.now();
            a.renders.push(now);
            if (document.body.dataset.ready === 'true' && p.toyInfo?.id === id && a.firstReadyRenderMs === null) a.firstReadyRenderMs = now;
          });
          p.on('action', value => a.actions.push({ at: performance.now(), ...value }));
        };
        requestAnimationFrame(attach);
        window.__perfSample = async (label, tap) => {
          const start = performance.now();
          if (tap) window.__splashery.app.act();
          await new Promise(resolve => setTimeout(resolve, 5000));
          const end = performance.now();
          const times = window.__perf.frameends.filter(t => t >= start && t <= end);
          const renders = window.__perf.renders.filter(t => t >= start && t <= end);
          const intervals = times.slice(1).map((t, i) => t - times[i]);
          const renderIntervals = renders.slice(1).map((t, i) => t - renders[i]);
          const sorted = [...intervals].sort((a, b) => a - b);
          const q = p => sorted.length ? sorted[Math.max(0, Math.ceil(sorted.length * p) - 1)] : null;
          const result = { label, startMs: start, endMs: end, elapsedMs: end - start, samples: intervals.length, renderCount: renders.length, medianMs: q(.5), p95Ms: q(.95), intervalsMs: intervals, renderIntervalsMs: renderIntervals };
          window.__perf.windows.push(result);
          return result;
        };
      }, { id: toy.id });
      const scene = createScene({ seed: 424242, toy: { kind: 'builtin', id: toy.id } });
      if (toy.camera) scene.camera = { ...scene.camera, ...toy.camera };
      if (holdsStill(toy)) scene.autoplay.turntable = false;
      const hash = `j.${Buffer.from(JSON.stringify(scene)).toString('base64url')}`;
      const url = `${base}/?renderer=webgl2&profile=${def.profile}&adapt=off&labs=${toy.labs ? 1 : 0}#s=${hash}`;
      const row = { id: toy.id, label: toy.label, labs: !!toy.labs, kind: toy.kind, pack: toy.pack || null, device: def.name, at: new Date().toISOString(), status: 'ok', collectorVersion: 3 };
      try {
        await page.goto(url, { waitUntil: 'domcontentloaded', timeout: 60000 });
        await page.waitForFunction(id => document.body.dataset.ready === 'true' && window.__splashery.player.toyInfo?.id === id && window.__perf.firstReadyRenderMs !== null, toy.id, { timeout: 120000 });
        phase = 'settling';
        row.heap = await cdp.send('Runtime.getHeapUsage');
        Object.assign(row, await page.evaluate(() => {
          const p = window.__splashery.player;
          const gl = p.stage.device.gl;
          const ext = gl?.getExtension('WEBGL_debug_renderer_info');
          return { firstReadyRenderMs: window.__perf.firstReadyRenderMs, splats: p.toyInfo.splats + (p.pictures?.splats() || 0), baseSplats: p.toyInfo.splats, pictureSplats: p.pictures?.splats() || 0, profile: p.profile, renderer: p.deviceType, gpu: ext ? gl.getParameter(ext.UNMASKED_RENDERER_WEBGL) : null, canvas: { width: p.canvas.width, height: p.canvas.height, cssWidth: p.canvas.clientWidth, cssHeight: p.canvas.clientHeight, pixelCap: p.stage.device.maxPixelRatio }, recipeDensity: p.toyInfo.recipe?.density ?? null, recipeTurntable: p.toyInfo.recipe?.turntable ?? null, soundEnabled: window.__splashery.app.sound.enabled, visible: document.visibilityState };
        }));
        const metrics = await cdp.send('Performance.getMetrics');
        row.navigationStartTimestamp = metrics.metrics.find(m => m.name === 'NavigationStart')?.value;
        row.openEncodedBytes = [...requests.values()].filter(r => r.finishTimestamp <= row.navigationStartTimestamp + row.firstReadyRenderMs / 1000).reduce((s, r) => s + (r.encodedBytes || 0), 0);
        row.openObservedEncodedBytes = [...requests.values()].filter(r => r.phaseFinished === 'opening').reduce((s, r) => s + (r.encodedBytes || 0), 0);
        await page.waitForTimeout(1500);
        row.settledSplats = await page.evaluate(() => window.__splashery.player.toyInfo.splats + (window.__splashery.player.pictures?.splats() || 0));
        row.heapAfterSettle = await cdp.send('Runtime.getHeapUsage');
        phase = 'idle';
        row.idle = await page.evaluate(() => window.__perfSample('idle', false));
        phase = 'tap';
        row.tap = await page.evaluate(() => window.__perfSample('tap', true));
        row.actions = await page.evaluate(() => window.__perf.actions);
        row.endSplats = await page.evaluate(() => window.__splashery.player.toyInfo.splats + (window.__splashery.player.pictures?.splats() || 0));
        row.resources = await page.evaluate(() => performance.getEntriesByType('resource').filter(r => /^https?:/.test(r.name)).map(r => ({ url: r.name, initiator: r.initiatorType, startMs: r.startTime, durationMs: r.duration, transferSize: r.transferSize, encodedBodySize: r.encodedBodySize, decodedBodySize: r.decodedBodySize })));
        row.workerResources = [];
        for (const worker of page.workers()) {
          try {
            const data = await worker.evaluate(() => ({ originMs: performance.timeOrigin, resources: performance.getEntriesByType('resource').filter(r => /^https?:/.test(r.name)).map(r => ({ url: r.name, initiator: r.initiatorType, startMs: r.startTime, durationMs: r.duration, transferSize: r.transferSize, encodedBodySize: r.encodedBodySize, decodedBodySize: r.decodedBodySize })) }));
            row.workerResources.push({ url: worker.url(), ...data });
          } catch (e) { row.workerResources.push({ url: worker.url(), error: String(e) }); }
        }
        row.timeOriginMs = await page.evaluate(() => performance.timeOrigin);
      } catch (e) {
        row.status = 'error'; row.error = String(e); console.log(`ERROR ${def.name} ${toy.id}: ${String(e).slice(0,240)}`);
      }
      row.requests = [...requests.values()];
      row.totalEncodedBytes = row.requests.reduce((s,r) => s + (r.encodedBytes || 0), 0);
      row.pageErrors = errors; row.consoleErrors = consoleErrors;
      rows = rows.filter(r => r.id !== toy.id);
      rows.push(row);
      write(filename, rows);
      await context.close();
      n++;
      console.log(`${new Date().toISOString()} ${def.name} ${rows.length}/${selected.length} ${toy.id} ${row.status} ${row.openEncodedBytes ?? '?'} B ${Math.round(row.firstReadyRenderMs ?? 0)} ms ${row.splats ?? '?'} splats idle=${row.idle?.p95Ms?.toFixed(1)} tap=${row.tap?.p95Ms?.toFixed(1)}`);
    }
  }
} finally { await browser.close(); }
console.log(`Finished ${n} measurements.`);
